-- create "practice_content_versions" table
CREATE TABLE "practice_content_versions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "version" bigint NOT NULL, PRIMARY KEY ("id"));
-- create "practice_subject_catalogs" table
CREATE TABLE "practice_subject_catalogs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "scope" character varying NOT NULL, "content_version" bigint NOT NULL, "format_version" bigint NOT NULL, "built_at" timestamptz NOT NULL, "items" jsonb NOT NULL, PRIMARY KEY ("id"));
-- create index "practice_subject_catalogs_scope_key" to table: "practice_subject_catalogs"
CREATE UNIQUE INDEX "practice_subject_catalogs_scope_key" ON "practice_subject_catalogs" ("scope");
